import { logger } from '../ui/logger';
import {
  SERVICE_UUID,
  CHAR_INTENT_UUID,
  CHAR_ACK_UUID,
  CHAR_STATUS_UUID,
  RELAY_NAME_PREFIX
} from './uuids';

/**
 * Web Bluetooth client wrapper around the BLE Pay relay (peripheral).
 *
 * Security note: requestDevice() must be called from a user gesture and over HTTPS
 * (or http://localhost). Payload integrity is checked at the protocol layer
 * (SHA-256 + TTL + nonce).
 */

export interface RelayHandles {
  device: BluetoothDevice;
  server: BluetoothRemoteGATTServer;
  service: BluetoothRemoteGATTService;
  intent: BluetoothRemoteGATTCharacteristic;
  ack: BluetoothRemoteGATTCharacteristic;
  status: BluetoothRemoteGATTCharacteristic | null;
}

export interface ConnectOptions {
  /** Operation timeout in ms. */
  timeoutMs?: number;
  /** If true, only filter by service UUID. If false, also accept the name prefix. */
  strict?: boolean;
}

const DEFAULT_TIMEOUT = 12_000;

/**
 * Wrap a promise with a timeout that rejects with a tagged error.
 */
function withTimeout<T>(p: Promise<T>, ms: number, label: string): Promise<T> {
  return new Promise<T>((resolve, reject) => {
    const t = setTimeout(() => reject(new Error(`Timeout after ${ms}ms: ${label}`)), ms);
    p.then(
      (v) => { clearTimeout(t); resolve(v); },
      (e) => { clearTimeout(t); reject(e); }
    );
  });
}

/**
 * Quick capability check. Web Bluetooth is only available on secure contexts.
 */
export function isBleAvailable(): boolean {
  return typeof navigator !== 'undefined'
    && 'bluetooth' in navigator
    && typeof (navigator as Navigator).bluetooth?.requestDevice === 'function';
}

/**
 * Prompt user to pick a relay device. MUST be called from a user gesture.
 */
export async function requestRelayDevice(opts: ConnectOptions = {}): Promise<BluetoothDevice> {
  if (!isBleAvailable()) {
    throw new Error('Web Bluetooth no disponible (requiere HTTPS y Chrome Android).');
  }
  logger.info('scan', 'Solicitando selector de dispositivos BLE…');
  const filters: BluetoothLEScanFilter[] = [{ services: [SERVICE_UUID] }];
  if (!opts.strict) {
    filters.push({ namePrefix: RELAY_NAME_PREFIX });
  }
  const device = await navigator.bluetooth.requestDevice({
    filters,
    optionalServices: [SERVICE_UUID]
  });
  logger.info('scan', `Dispositivo elegido: ${device.name ?? '(sin nombre)'} [${device.id}]`);
  return device;
}

/**
 * Connect to a previously chosen device and resolve all relevant GATT handles.
 */
export async function connectRelay(
  device: BluetoothDevice,
  opts: ConnectOptions = {}
): Promise<RelayHandles> {
  const timeoutMs = opts.timeoutMs ?? DEFAULT_TIMEOUT;
  if (!device.gatt) throw new Error('El dispositivo no expone GATT.');

  logger.info('connect', `GATT.connect() → ${device.name ?? device.id}`);
  const server = await withTimeout(device.gatt.connect(), timeoutMs, 'gatt.connect');

  logger.info('connect', `getPrimaryService(${SERVICE_UUID})`);
  const service = await withTimeout(server.getPrimaryService(SERVICE_UUID), timeoutMs, 'getPrimaryService');

  const [intent, ack, status] = await Promise.all([
    withTimeout(service.getCharacteristic(CHAR_INTENT_UUID), timeoutMs, 'char:intent'),
    withTimeout(service.getCharacteristic(CHAR_ACK_UUID),    timeoutMs, 'char:ack'),
    service.getCharacteristic(CHAR_STATUS_UUID).catch(() => null)
  ]);

  logger.info('connect', 'GATT listo (intent/ack/status resueltos)');
  return { device, server, service, intent, ack, status };
}

/**
 * Read the current PaymentIntent JSON bytes from the relay.
 */
export async function readIntent(h: RelayHandles, timeoutMs = DEFAULT_TIMEOUT): Promise<Uint8Array> {
  logger.info('read', 'Leyendo characteristic INTENT');
  const dv = await withTimeout(h.intent.readValue(), timeoutMs, 'read:intent');
  const bytes = new Uint8Array(dv.buffer, dv.byteOffset, dv.byteLength);
  logger.debug('read', `INTENT ${bytes.byteLength} bytes`);
  return bytes;
}

/**
 * Write a PaymentIntent JSON to the relay (used by the receiver in "Cobrar").
 */
export async function writeIntent(h: RelayHandles, payload: Uint8Array, timeoutMs = DEFAULT_TIMEOUT): Promise<void> {
  logger.info('write', `Publicando INTENT (${payload.byteLength} bytes)`);
  // writeValueWithResponse provides delivery confirmation.
  await withTimeout(h.intent.writeValueWithResponse(payload), timeoutMs, 'write:intent');
}

/**
 * Write the Ack JSON back to the relay (used by the payer in "Pagar").
 */
export async function writeAck(h: RelayHandles, payload: Uint8Array, timeoutMs = DEFAULT_TIMEOUT): Promise<void> {
  logger.info('write', `Escribiendo ACK (${payload.byteLength} bytes)`);
  await withTimeout(h.ack.writeValueWithResponse(payload), timeoutMs, 'write:ack');
}

/**
 * Subscribe to ACK notifications. Used by the receiver to detect payer Ack.
 * Returns an unsubscribe function.
 */
export async function subscribeAck(
  h: RelayHandles,
  onValue: (bytes: Uint8Array) => void,
  timeoutMs = DEFAULT_TIMEOUT
): Promise<() => Promise<void>> {
  logger.info('notify', 'Activando notificaciones en ACK');
  await withTimeout(h.ack.startNotifications(), timeoutMs, 'startNotifications:ack');
  const handler = (ev: Event) => {
    const target = ev.target as BluetoothRemoteGATTCharacteristic;
    const v = target.value;
    if (!v) return;
    const bytes = new Uint8Array(v.buffer, v.byteOffset, v.byteLength);
    logger.debug('notify', `ACK notify ${bytes.byteLength} bytes`);
    onValue(bytes);
  };
  h.ack.addEventListener('characteristicvaluechanged', handler);
  return async () => {
    h.ack.removeEventListener('characteristicvaluechanged', handler);
    try { await h.ack.stopNotifications(); } catch { /* device may be gone */ }
  };
}

/**
 * Subscribe to INTENT notifications (payer side may listen for new intents
 * if the receiver re-publishes one without disconnecting).
 */
export async function subscribeIntent(
  h: RelayHandles,
  onValue: (bytes: Uint8Array) => void,
  timeoutMs = DEFAULT_TIMEOUT
): Promise<() => Promise<void>> {
  logger.info('notify', 'Activando notificaciones en INTENT');
  await withTimeout(h.intent.startNotifications(), timeoutMs, 'startNotifications:intent');
  const handler = (ev: Event) => {
    const target = ev.target as BluetoothRemoteGATTCharacteristic;
    const v = target.value;
    if (!v) return;
    const bytes = new Uint8Array(v.buffer, v.byteOffset, v.byteLength);
    onValue(bytes);
  };
  h.intent.addEventListener('characteristicvaluechanged', handler);
  return async () => {
    h.intent.removeEventListener('characteristicvaluechanged', handler);
    try { await h.intent.stopNotifications(); } catch { /* device may be gone */ }
  };
}

/**
 * Reconnect with simple exponential backoff. Honors gattserverdisconnected events.
 * Resource cleanup: callers MUST disconnect when done (see disconnect()).
 */
export async function reconnect(
  device: BluetoothDevice,
  attempts = 4
): Promise<RelayHandles> {
  let delay = 500;
  let lastErr: unknown;
  for (let i = 1; i <= attempts; i++) {
    try {
      logger.info('connect', `Reintento ${i}/${attempts}`);
      const handles = await connectRelay(device);
      return handles;
    } catch (e) {
      lastErr = e;
      logger.warn('connect', `Falló intento ${i}: ${(e as Error).message}`);
      await new Promise((r) => setTimeout(r, delay));
      delay = Math.min(delay * 2, 4000);
    }
  }
  throw lastErr instanceof Error ? lastErr : new Error('reconnect failed');
}

/**
 * Cleanly disconnect from the relay. Always call when leaving a screen.
 */
export function disconnect(h: RelayHandles | null | undefined): void {
  if (!h) return;
  try {
    if (h.server.connected) h.server.disconnect();
    logger.info('connect', 'GATT desconectado');
  } catch (e) {
    logger.warn('connect', `Error al desconectar: ${(e as Error).message}`);
  }
}
